import { SECONDS_PER_HOUR } from "../../constants";

// 矿条熔炼配方定义（Smeltery Recipes）
// 每级产出 1 个对应矿条，消耗递增，熔炼时间随批次递增（MINING_SMELTERY_TIME_INCREMENT）
// 矿石/主料：1.002^lvl（低增长，可持续产出）
// 附属材料：1.002^lvl 或线性增长（氦气），已取消高倍率 1.01 增长

export default {
    // 铝锭（轻量）：镐制作品质 +50%/级，矿石品质 2^lvl
    // 配方：铝矿石 1.002^lvl / 10 + 花岗岩 1.002^lvl × 100
    // 初期配方，消耗最低，产量最大
    aluminium: {
        price(lvl) {
            return {
                mining_oreAluminium: 100* lvl,
                mining_granite: 1000*lvl,
            };
        },
        output: 'mining_barAluminium',
        timeNeeded: 0,
        minTemperature: 100
    },
    // 青铜锭（坚固）：矿石获取 +10%/级（复合），稀土获取 +15%/级（复合）
    // 配方：铜矿石 1.002^lvl / 10 + 锡矿石 1.002^lvl / 100 + 盐 1.002^lvl × 10
    // 铜:锡:盐 = 10:1:1000，全部同倍率增长
    bronze: {
        price(lvl) {
            return {
                mining_oreCopper: Math.pow(1.002, lvl) / 10,
                mining_oreTin: Math.pow(1.002, lvl) / 100,
                mining_salt: Math.pow(1.002, lvl) * 10,
            };
        },
        output: 'mining_barBronze',
        timeNeeded: 5,
        minTemperature: 275
    },
    // 钢锭（锋利）：伤害 +12%/级，韧性 /1.5^lvl
    // 钢锭（锋利）：伤害 +12%/级，韧性 /1.5^lvl
    // 配方：铁矿石 1.002^lvl / 10 + 煤 ×1（固定，不随等级增长）
    // 煤消耗永远为 1，是该配方的主要优势
    steel: {
        price(lvl) {
            return {
                mining_oreIron: Math.pow(1.002, lvl) / 10,
                mining_coal: 1,
            };
        },
        output: 'mining_barSteel',
        timeNeeded: 10,
        minTemperature: 500
    },
    // 钛锭（挖掘机）：废料获取累加提升
    // 配方：钛矿石 1.002^lvl / 10 + 硫磺 1.002^lvl × 10 + 硝石 ×10（固定）
    // 硫磺消耗随等级增长，硝石始终为 10
    titanium: {
        price(lvl) {
            return {
                mining_oreTitanium: Math.pow(1.002, lvl) / 10,
                mining_sulfur: Math.pow(1.002, lvl) * 10,
                mining_niter: 10,
            };
        },
        output: 'mining_barTitanium',
        timeNeeded: 15,
        minTemperature: 800
    },
    // 闪亮锭（富有）：深潜者速度 +10%/级，绿色水晶获取 +50%/级
    // 配方：铂矿石 1.002^lvl / 10 + 黑曜石 1.002^lvl × 10
    // 黑曜石消耗与铂矿同比例增长
    shiny: {
        price(lvl) {
            return {
                mining_orePlatinum: Math.pow(1.002, lvl) / 10,
                mining_obsidian: Math.pow(1.002, lvl) * 10,
            };
        },
        output: 'mining_barShiny',
        timeNeeded: 20,
        minTemperature: 1250
    },
    // 铱锭（熔融）：余烬获取 +30%/级
    // 配方：铱矿石 1.002^lvl / 100 + 氦气 lvl × 10（线性增长）
    // 铱矿石指数增长、氦气线性增长，气体需求不会失控
    iridium: {
        price(lvl) {
            return {
                mining_oreIridium: Math.pow(1.002, lvl) / 100,
                mining_helium: lvl * 10,
            };
        },
        output: 'mining_barIridium',
        timeNeeded: 30,
        minTemperature: 2000
    },
    // 暗铁锭（虚空）：废料容量累加提升
    // 配方：铁矿石 1.002^lvl × 10 + 锇矿石 1.002^lvl × 10
    //      + 深岩 1.002^lvl × 100 + 氖气 lvl × 1000（线性增长）
    // 终极配方，矿石指数增长、气体线性增长
    darkIron: {
        price(lvl) {
            return {
                mining_oreIron: Math.pow(1.002, lvl) * 10,
                mining_oreOsmium: Math.pow(1.002, lvl) * 10,
                mining_deeprock: Math.pow(1.002, lvl) * 100,
                mining_neon: lvl * 1000,
            };
        },
        output: 'mining_barDarkIron',
        timeNeeded: SECONDS_PER_HOUR,
        minTemperature: 3000
    },
}
